L32_1 = {}
L32_1.m_CutScenKey_Talk = "CHOCOLAT_SUPPLEMENT_INTERLUDE4@19#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 7200111
