L32_1.m_CharStrID = "ELIZABETH_PRYDWEN_NULL_NULL"
L32_1.m_Pos = "L"
L32_1.m_Talk_KOREA = "명심해두세요. 모든 사람들은 저마다의 격을 가지기 마련이죠."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "肝に銘じておきなさい。すべての人はそれぞれの格を持っているのです。"
L32_1.m_Talk_ENG = "Keep in mind, everyone has their own level of dignity to uphold."
L32_1.m_Talk_TWN = "請記住，每個人都有屬於自己的格調。"
L32_1.m_Talk_SCN = "请记住，每个人都有属于自己的格调。"
L32_1.m_Talk_DEU = "Keep in mind, everyone has their own level of dignity to uphold."
L32_1.m_Talk_FRA = "Keep in mind, everyone has their own level of dignity to uphold."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "CHOCOLAT_SUPPLEMENT_INTERLUDE4@20#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 7200111
