L33_1.m_Face = "UNIT_SERIOUS"
L33_1.m_CharStrID = "ELIZABETH_PRYDWEN_NULL_NULL"
L33_1.m_Pos = "L"
L33_1.m_Talk_KOREA = "하지만 저같이 고귀한 품격을 가진 인물은 서있는 곳 자체가 그에 걸맞은 의미를 가지게 된답니다."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "ですが、私のような高貴な品格を持っている人物は、立っている場所自体がそれ相応の意味を持つのですわ。"
L33_1.m_Talk_ENG = "But for a person of noble character like me being here has its own meaning."
L33_1.m_Talk_TWN = "但是像我這樣擁有高貴品格的人，所站的地方本身就會賦予其相符的意義。"
L33_1.m_Talk_SCN = "但是像我这样拥有高贵品格的人，所站的地方本身就会赋予其相应的意义。"
L33_1.m_Talk_DEU = "But for a person of noble character like me being here has its own meaning."
L33_1.m_Talk_FRA = "But for a person of noble character like me being here has its own meaning."
